# A minimal supervised learning example
training = [
    ({"height": 150}, "short"),
    ({"height": 170}, "medium"),
    ({"height": 190}, "tall"),
]

def simple_model(height):
    if height < 160:
        return "short"
    elif height < 180:
        return "medium"
    else:
        return "tall"

print(simple_model(155))   # short
print(simple_model(185))   # tall
